rss.channel:
{{ feed.title|e }}
{{ feed.link|e }}
{{ feed.description|e }}
{% for item in items %}


	{{ item.id|e }}
	{{ item.title|e }}
	{{ item.description|e }}
	{{ item.link|e }}
	{{ item.image_link|e }}
	{{ item.price|e }}
	{% if item.sale_price %}
	{{ item.sale_price|e }}
	{% endif %}
	{{ item.availability|e }}
	{{ item.condition|e }}
	{% if item.brand %}
	{{ item.brand|e }}
	{% endif %}
	{% if item.gtin %}
	{{ item.gtin|e }}
	{% endif %}
	{% if item.mpn %}
	{{ item.mpn|e }}
	{% endif %}
	{% if item.identifier_exists %}
	{{ item.identifier_exists|e }}
	{% endif %}
	{% if item.item_group_id %}
	{{ item.item_group_id|e }}
	{% endif %}
	{% if item.size %}
	{{ item.size|e }}
	{% endif %}
	{% if item.color %}
	{{ item.color|e }}
	{% endif %}
	{% if item.material %}
	{{ item.material|e }}
	{% endif %}
	{% if item.pattern %}
	{{ item.pattern|e }}
	{% endif %}
	{% if item.product_type %}
	{{ item.product_type|e }}
	{% endif %}
	{% if google_product_category %}
	{{ google_product_category|e }}
	{% endif %}
	{% if shipping %}

		{{ shipping.country|e }}
		{{ shipping.service|e }}
		{{ shipping.price|e }}

	{% endif %}
	{% if item.returns %}

		{{ item.returns.country|e }}
		{{ item.returns.item_condition|e }}
		{{ item.returns.window_days|e }}
		{{ item.returns.window_type|e }}
		{{ item.returns.method|e }}
		{{ item.returns.outcome|e }}
		{{ item.returns.shipping_fee|e }}
		{{ item.returns.shipping_fee_type|e }}

	{% endif %}

{% endfor %}
